class RateOfChangeRule:
    def __init__(self, sensor_id: str, max_change_per_minute: float,
                 level: Level = Level.WARNING) -> None:
        if max_change_per_minute <= 0:
            raise ValueError("max_change_per_minute 必須大於 0")
        self.sensor_id = sensor_id
        self.max_change_per_minute = max_change_per_minute
        self.level = level
        self._previous: Reading | None = None

    def check(self, reading: Reading) -> Alert | None:
        if reading.sensor_id != self.sensor_id:
            return None
        previous, self._previous = self._previous, reading
        if previous is None:
            return None
        minutes = (reading.at - previous.at).total_seconds() / 60
        if minutes <= 0:
            return None
        rate = abs(reading.value - previous.value) / minutes
        if rate <= self.max_change_per_minute:
            return None
        return Alert(reading, self.level,
                     f"{reading.sensor_id} 變化過快：{rate:.2f}{reading.unit}/min"
                     f"（上限 {self.max_change_per_minute}{reading.unit}/min）")

class CooldownNotifier:
    def __init__(self, inner: Notifier, cooldown: timedelta) -> None:
        if cooldown <= timedelta(0):
            raise ValueError("cooldown 必須大於 0")
        self._inner = inner
        self._cooldown = cooldown
        self._last_sent: dict[tuple[str, Level], datetime] = {}
        self.suppressed = 0

    def notify(self, alert: Alert) -> None:
        key = (alert.sensor_id, alert.level)
        now = alert.reading.at
        last = self._last_sent.get(key)
        if last is not None and now - last < self._cooldown:
            self.suppressed += 1
            return
        self._last_sent[key] = now
        self._inner.notify(alert)

